@Bean
RestClient providerClient(RestClient.Builder builder,
        @Value("${api.base-url}") String baseUrl) {
    HttpClient http = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(3)).build();
    var factory = new JdkClientHttpRequestFactory(http);
    factory.setReadTimeout(Duration.ofSeconds(5));
    return builder.baseUrl(baseUrl).requestFactory(factory).build();
}

record Weather(String city, double temperatureC) {}

Weather weather = providerClient.get()
        .uri(b -> b.path("/weather").queryParam("city", "Pune").build())
        .retrieve().body(Weather.class);

record AnalysisRequest(String text) {}
record AnalysisResult(String label) {}

AnalysisResult result = providerClient.post().uri("/analyses")
        .contentType(MediaType.APPLICATION_JSON)
        .body(new AnalysisRequest("Today went well."))
        .retrieve().body(AnalysisResult.class);
